begin;create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table programme_directory_fixture(pack uuid,reference uuid,programme uuid);grant select,insert,update on programme_directory_fixture to cuevo_api;
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
insert into programme_directory_fixture(pack)select(internal.configure_curriculum('version.create',null,'{"packId":"directory-golden","kind":"school_custom","framework":"School Custom","programme":"Directory technical source","version":"directory-1","scope":"synthetic","sourceStatus":"VERIFIED","rightsStatus":"PERMITTED","sourceLocation":"repo:synthetic","sourceChecksum":null,"synthetic":true,"reason":"Source-bound directory test"}','directory-pack',repeat('a',64),'directory')->>'id')::uuid;
update programme_directory_fixture set reference=(internal.configure_curriculum('reference.create',null,jsonb_build_object('packVersionId',pack,'parentId',null,'type','objective','title','School directory objective','description','Explicit school authored objective.','code',null,'sequence',1,'subjectId','43000000-0000-4000-8000-000000000001','yearGroupId','42000000-0000-4000-8000-000000000001'),'directory-reference',repeat('b',64),'directory')->>'id')::uuid;
select internal.transition_curriculum_lifecycle((select pack from programme_directory_fixture),'{"state":"APPROVED","expectedRevision":1,"reviewBasis":"SCHOOL_AUTHORED","artifactDirectory":null,"replacementVersionId":null,"reason":"School reviews synthetic directory source.","confirmTransition":true}',null,'directory-reviewed',repeat('c',64),'directory')is not null as reviewed;
select internal.transition_curriculum_lifecycle((select pack from programme_directory_fixture),'{"state":"ACTIVE","expectedRevision":2,"reviewBasis":"SCHOOL_AUTHORED","artifactDirectory":null,"replacementVersionId":null,"reason":"School activates synthetic directory source.","confirmTransition":true}',null,'directory-active',repeat('d',64),'directory')is not null as activated;
update programme_directory_fixture set programme=(internal.configure_curriculum('programme.create',null,jsonb_build_object('packVersionId',pack,'name','Directory programme','classId','30000000-0000-4000-8000-000000000001','subjectId','43000000-0000-4000-8000-000000000001','yearGroupId','42000000-0000-4000-8000-000000000001','confirmConfiguration',true),'directory-programme',repeat('e',64),'directory')->>'id')::uuid;
select internal.configure_curriculum('learner.configure',null,jsonb_build_object('programmeId',(select programme from programme_directory_fixture),'learnerId','20000000-0000-4000-8000-000000000012','status','active','confirmAccessChange',true),'directory-learner-a',repeat('f',64),'directory')is not null as assigned;
select internal.configure_curriculum('learner.configure',null,jsonb_build_object('programmeId',(select programme from programme_directory_fixture),'learnerId','20000000-0000-4000-8000-000000000018','status','active','confirmAccessChange',true),'directory-learner-b',repeat('a',64),'directory')is not null as assigned;
select ok((select item?&array['className','subjectName','yearGroupName','academicYearName','framework','packProgramme','packVersion']from jsonb_array_elements(internal.read_curriculum_programmes(100,null)->'items')item where item->>'id'=(select programme::text from programme_directory_fixture)),'Programme page provides human current source context');
select is(internal.read_curriculum_programme_learners((select programme from programme_directory_fixture),1,null)->'items'->0->>'learnerId','20000000-0000-4000-8000-000000000012','Current assignment page selects one exact learner');
select is(internal.read_curriculum_programme_learners((select programme from programme_directory_fixture),1,null)->>'nextCursor','20000000-0000-4000-8000-000000000012','Assignment continuation uses exact learner identity');
select is(internal.read_curriculum_programme_learners((select programme from programme_directory_fixture),1,'20000000-0000-4000-8000-000000000012')->'items'->0->>'learnerId','20000000-0000-4000-8000-000000000018','Later assignment remains reachable');
select internal.configure_curriculum('learner.configure',null,jsonb_build_object('programmeId',(select programme from programme_directory_fixture),'learnerId','20000000-0000-4000-8000-000000000012','status','revoked','confirmAccessChange',true),'directory-revoke',repeat('b',64),'directory')is not null as revoked;
select is(internal.read_curriculum_programme_learners((select programme from programme_directory_fixture),25,null)->'items'->0->>'status','revoked','Revoked programme decision remains explicit current readback');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000005',true);select throws_ok($$select internal.read_curriculum_programme_learners((select programme from programme_directory_fixture),25,null)$$,'42501',null,'Unassigned teacher cannot read programme learners');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);select throws_ok($$select internal.read_curriculum_programme_learners((select programme from programme_directory_fixture),25,null)$$,'42501',null,'Parent cannot read staff programme assignment directory');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);select throws_ok($$select internal.read_curriculum_programmes(25,null)$$,'42501',null,'Student cannot enumerate staff programmes');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);select throws_ok($$select internal.read_curriculum_programme_learners('90000000-0000-4000-8000-000000000001',25,null)$$,'42501',null,'Unknown foreign programme denies before directory expansion');
select ok(not has_function_privilege('authenticated','internal.read_curriculum_programme_learners(uuid,integer,uuid)','execute'),'Data API cannot call staff assignment source');select ok(not has_function_privilege('cuevo_worker','internal.read_curriculum_programmes(integer,uuid)','execute'),'Worker receives no directory context grant');
reset role;update app.enrollments set status='revoked'where school_id='10000000-0000-4000-8000-000000000001'and class_id='30000000-0000-4000-8000-000000000001'and student_actor_id='20000000-0000-4000-8000-000000000012';set local role cuevo_api;select is(jsonb_array_length(internal.read_curriculum_programme_learners((select programme from programme_directory_fixture),25,null)->'items'),1,'Transferred learner no longer appears in current assignment scope');reset role;
select*from finish();rollback;
